head.script:
scwin.key_edu_schdl_id;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        await scwin.setCode();
        await scwin.setYear();
        await scwin.searchPage();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30616.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.searchPage();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30616.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnFail
 * @description MASTER On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnFail = async function() {
    try {
        await $c.win.alert(dts_MASTER);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30616.dts_MASTER_OnFail" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadError
 * @description dts_MASTER 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_MASTER);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30616.dts_MASTER_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadCompleted
 * @description dts_MASTER 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_MASTER.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30616.dts_MASTER_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnClick = function(row, colid) {
    try {
        scwin.setKey(dts_MASTER.getCellData(row, "EDU_SCHDL_ID"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30616.grd_Grid_OnClick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (colid === 'DISCLS_EDU_CRS_NM') {
            await scwin.readDisclsEdu(row, colid);
        } else if (colid === 'EDU_TM') {
            await scwin.readDisclsEduExcelUpload(row, colid);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30616.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Input_onclick = async function() {
    try {
        scwin.key_edu_schdl_id = "";
        const options = {
            id: "ULDSTF30617",
            title: "공시교육일정 등록",
            type: "browserPopup",
            width: "100px",
            height: "100px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/issueinfo/ULDSTF30617.gfm ", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30616.btn_Input_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF30616.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "공시교육일정등록현황", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30616.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    // dts_year.DataID = encodeURI("/ListedCompany.do?method=selectMinMaxYear&outputMessageId=DISCLS_MIN_MAX_YEAR_OUT");
    // dts_year.Reset();

    const sbmOptions = {
        id : "sbm_dts_edu",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_edu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setYear
 * @description set Year 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setYear = async function() {
    const sbmOptions = {
        id : "sbm_dts_year",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_year=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const minYear = dts_year.getCellData(1, "MIN_YEAR");
    const maxYear = dts_year.getCellData(1, "MAX_YEAR");
    let str = "^전체";
    for (let i = maxYear; i >= minYear; i--) {
        str += "," + i + "%^" + i;
    }
    // alert(str);
    cmb_OBJ_YY.CBData = str;

    // default 현재년도
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    cmb_OBJ_YY.setValue(yyyy + "%");
};

/**
 * @method
 * @name searchPage
 * @description search Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchPage = async function() {
    url += "&EDU_KIND_CD=" + cmb_EDU_KIND_CD.getValue(); // 담당자구분
    url += "&OBJ_YY=" + cmb_OBJ_YY.getValue(); // 대상년도
    url += "&SECU_EDU_TP_CD=" + cmb_edu.getValue(); // 교육구분
    url += "&SCREN_ID=" + "ULDSTF30616.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description 공시교육일정 등록 후 페이지 search 함    -> fn_Search_Page 로 변경
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&EDU_KIND_CD=" + cmb_EDU_KIND_CD.getValue();
    url += "&OBJ_YY=" + cmb_OBJ_YY.getValue();
    url += "&SECU_EDU_TP_CD=" + cmb_edu.getValue(); // 교육구분
    url += "&SCREN_ID=" + "ULDSTF30616.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    await scwin.setCode();
    await scwin.setYear();
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setKey
 * @description set Key 처리
 * @param {*} id id
 * @returns {void}
 * @hidden N
 */
scwin.setKey = function(id) {
    scwin.key_edu_schdl_id = id;
};

/**
 * @method
 * @name readDisclsEdu
 * @description read Discls Edu 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readDisclsEdu = async function(row, colid) {
    const options = {
        id: "ULDSTF30617",
        title: "공시교육일정 등록",
        type: "browserPopup",
        width: "100px",
        height: "100px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/issueinfo/ULDSTF30617.gfm", options);
};

// 교육시간 클릭 시 팝업(엑셀 일괄업로드 기능)

/**
 * @method
 * @name readDisclsEduExcelUpload
 * @description read Discls Edu Excel Upload 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readDisclsEduExcelUpload = async function(row, colid) {
    const options = {
        id: "ULDSTF30626",
        title: "공시교육참가현황 일괄 등록",
        type: "browserPopup",
        width: "100px",
        height: "100px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/issueinfo/ULDSTF30626.gfm", options);
};
